"use client";
/* Elephant, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Elephant(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("elephant"); }, []);
  return React.createElement("piix-sprite", { "name": "elephant", ...piixAttrs(props) });
}

export default Elephant;
